-- =====================================================================
-- V1__baseline.sql
-- CardDemo Walking Skeleton - Oracle Database 23ai baseline schema.
-- Runs as user CARDDEMO inside PDB FREEPDB1 (unqualified names).
-- Derived from legacy VSAM copybooks [SRC: CARDDEMO.CSD].
-- Flyway v11 (Community, Oracle) - plain ;-terminated statements only.
-- Surrogate PKs: NUMBER GENERATED BY DEFAULT AS IDENTITY (avoids ORA-32795).
-- Natural keys retained as UNIQUE; the one in-scope FK references a UNIQUE col.
-- =====================================================================

-- 1. USERS  [SRC: CSUSR01Y | USRSEC]
CREATE TABLE USERS (
    USER_SK     NUMBER GENERATED BY DEFAULT AS IDENTITY CONSTRAINT PK_USERS PRIMARY KEY,
    USER_ID     VARCHAR2(8)  NOT NULL,
    FIRST_NAME  VARCHAR2(20),
    LAST_NAME   VARCHAR2(20),
    PASSWORD    VARCHAR2(8),
    USER_TYPE   CHAR(1),
    CONSTRAINT UQ_USERS_USER_ID UNIQUE (USER_ID)
);

-- 2. ACCOUNT  [SRC: CVACT01Y | ACCTDAT]
CREATE TABLE ACCOUNT (
    ACCOUNT_SK              NUMBER GENERATED BY DEFAULT AS IDENTITY CONSTRAINT PK_ACCOUNT PRIMARY KEY,
    ACCT_ID                 NUMBER(11) NOT NULL,
    ACCT_ACTIVE_STATUS      CHAR(1),
    ACCT_CURR_BAL           NUMBER(12,2),
    ACCT_CREDIT_LIMIT       NUMBER(12,2),
    ACCT_CASH_CREDIT_LIMIT  NUMBER(12,2),
    ACCT_OPEN_DATE          VARCHAR2(10),
    ACCT_EXPIRAION_DATE     VARCHAR2(10),
    ACCT_REISSUE_DATE       VARCHAR2(10),
    ACCT_CURR_CYC_CREDIT    NUMBER(12,2),
    ACCT_CURR_CYC_DEBIT     NUMBER(12,2),
    ACCT_ADDR_ZIP           VARCHAR2(10),
    ACCT_GROUP_ID           VARCHAR2(10),
    CONSTRAINT UQ_ACCOUNT_ACCT_ID UNIQUE (ACCT_ID)
);

-- 3. CUSTOMER  [SRC: CVCUS01Y | CUSTDAT]
CREATE TABLE CUSTOMER (
    CUSTOMER_SK               NUMBER GENERATED BY DEFAULT AS IDENTITY CONSTRAINT PK_CUSTOMER PRIMARY KEY,
    CUST_ID                   NUMBER(9) NOT NULL,
    CUST_FIRST_NAME           VARCHAR2(25),
    CUST_MIDDLE_NAME          VARCHAR2(25),
    CUST_LAST_NAME            VARCHAR2(25),
    CUST_ADDR_LINE_1          VARCHAR2(50),
    CUST_ADDR_LINE_2          VARCHAR2(50),
    CUST_ADDR_LINE_3          VARCHAR2(50),
    CUST_ADDR_STATE_CD        VARCHAR2(2),
    CUST_ADDR_COUNTRY_CD      VARCHAR2(3),
    CUST_ADDR_ZIP             VARCHAR2(10),
    CUST_PHONE_NUM_1          VARCHAR2(15),
    CUST_PHONE_NUM_2          VARCHAR2(15),
    CUST_SSN                  NUMBER(9),
    CUST_GOVT_ISSUED_ID       VARCHAR2(20),
    CUST_DOB                  VARCHAR2(10),
    CUST_EFT_ACCOUNT_ID       VARCHAR2(10),
    CUST_PRI_CARD_HOLDER_IND  CHAR(1),
    CUST_FICO_CREDIT_SCORE    NUMBER(3),
    CONSTRAINT UQ_CUSTOMER_CUST_ID UNIQUE (CUST_ID)
);

-- 4. CARD  [SRC: CVACT02Y | CARDDAT]  -- TRACER table; CARD_NUM is the natural read key
CREATE TABLE CARD (
    CARD_SK             NUMBER GENERATED BY DEFAULT AS IDENTITY CONSTRAINT PK_CARD PRIMARY KEY,
    CARD_NUM            VARCHAR2(16) NOT NULL,
    CARD_ACCT_ID        NUMBER(11),
    -- CARD_CVV_CD is intentionally NOT stored. The CVV is sensitive card data
    -- (CARD-CVV-CD in the legacy CARDDAT record) and is deliberately excluded
    -- from the skeleton schema AND seed (finding P7-M16): the read DTO never
    -- exposes it and no entity/repository/mapper maps it. [SRC: CVACT02Y | CARDDAT]
    CARD_EMBOSSED_NAME  VARCHAR2(50),
    CARD_EXPIRAION_DATE VARCHAR2(10),
    CARD_ACTIVE_STATUS  CHAR(1),
    CONSTRAINT UQ_CARD_CARD_NUM UNIQUE (CARD_NUM),
    CONSTRAINT FK_CARD_ACCT FOREIGN KEY (CARD_ACCT_ID) REFERENCES ACCOUNT (ACCT_ID)
);

-- 5. CARD_XREF  [SRC: CVACT03Y | CCXREF]
CREATE TABLE CARD_XREF (
    CARD_XREF_SK   NUMBER GENERATED BY DEFAULT AS IDENTITY CONSTRAINT PK_CARD_XREF PRIMARY KEY,
    XREF_CARD_NUM  VARCHAR2(16) NOT NULL,
    XREF_CUST_ID   NUMBER(9),
    XREF_ACCT_ID   NUMBER(11),
    CONSTRAINT UQ_CARD_XREF_CARD_NUM UNIQUE (XREF_CARD_NUM)
);

-- 6. TRANSACTION  [SRC: CVTRA05Y | TRANSACT]
CREATE TABLE TRANSACTION (
    TRANSACTION_SK      NUMBER GENERATED BY DEFAULT AS IDENTITY CONSTRAINT PK_TRANSACTION PRIMARY KEY,
    TRAN_ID             VARCHAR2(16) NOT NULL,
    TRAN_TYPE_CD        VARCHAR2(2),
    TRAN_CAT_CD         NUMBER(4),
    TRAN_SOURCE         VARCHAR2(10),
    TRAN_DESC           VARCHAR2(100),
    TRAN_AMT            NUMBER(11,2),
    TRAN_MERCHANT_ID    NUMBER(9),
    TRAN_MERCHANT_NAME  VARCHAR2(50),
    TRAN_MERCHANT_CITY  VARCHAR2(50),
    TRAN_MERCHANT_ZIP   VARCHAR2(10),
    TRAN_CARD_NUM       VARCHAR2(16),
    TRAN_ORIG_TS        VARCHAR2(26),
    TRAN_PROC_TS        VARCHAR2(26),
    CONSTRAINT UQ_TRANSACTION_TRAN_ID UNIQUE (TRAN_ID)
);

-- 7. TRANSACTION_TYPE  [SRC: CVTRA03Y]
CREATE TABLE TRANSACTION_TYPE (
    TRANSACTION_TYPE_SK NUMBER GENERATED BY DEFAULT AS IDENTITY CONSTRAINT PK_TRANSACTION_TYPE PRIMARY KEY,
    TRAN_TYPE           VARCHAR2(2) NOT NULL,
    TRAN_TYPE_DESC      VARCHAR2(50),
    CONSTRAINT UQ_TRANSACTION_TYPE UNIQUE (TRAN_TYPE)
);

-- 8. TRANSACTION_CATEGORY  [SRC: CVTRA04Y]  -- composite natural key
CREATE TABLE TRANSACTION_CATEGORY (
    TRANSACTION_CATEGORY_SK NUMBER GENERATED BY DEFAULT AS IDENTITY CONSTRAINT PK_TRANSACTION_CATEGORY PRIMARY KEY,
    TRAN_TYPE_CD            VARCHAR2(2) NOT NULL,
    TRAN_CAT_CD             NUMBER(4)   NOT NULL,
    TRAN_CAT_TYPE_DESC      VARCHAR2(50),
    CONSTRAINT UQ_TRAN_CATEGORY UNIQUE (TRAN_TYPE_CD, TRAN_CAT_CD)
);

-- 9. DISCLOSURE_GROUP  [SRC: CVTRA02Y]  -- composite natural key
CREATE TABLE DISCLOSURE_GROUP (
    DISCLOSURE_GROUP_SK NUMBER GENERATED BY DEFAULT AS IDENTITY CONSTRAINT PK_DISCLOSURE_GROUP PRIMARY KEY,
    DIS_ACCT_GROUP_ID   VARCHAR2(10) NOT NULL,
    DIS_TRAN_TYPE_CD    VARCHAR2(2)  NOT NULL,
    DIS_TRAN_CAT_CD     NUMBER(4)    NOT NULL,
    DIS_INT_RATE        NUMBER(6,2),
    CONSTRAINT UQ_DISCLOSURE_GROUP UNIQUE (DIS_ACCT_GROUP_ID, DIS_TRAN_TYPE_CD, DIS_TRAN_CAT_CD)
);

-- 10. TRANSACTION_CATEGORY_BALANCE  [SRC: CVTRA01Y]  -- composite natural key
CREATE TABLE TRANSACTION_CATEGORY_BALANCE (
    TRAN_CAT_BAL_SK   NUMBER GENERATED BY DEFAULT AS IDENTITY CONSTRAINT PK_TRAN_CAT_BAL PRIMARY KEY,
    TRANCAT_ACCT_ID   NUMBER(11) NOT NULL,
    TRANCAT_TYPE_CD   VARCHAR2(2) NOT NULL,
    TRANCAT_CD        NUMBER(4)   NOT NULL,
    TRAN_CAT_BAL      NUMBER(11,2),
    CONSTRAINT UQ_TRAN_CAT_BAL UNIQUE (TRANCAT_ACCT_ID, TRANCAT_TYPE_CD, TRANCAT_CD)
);

-- Alternate-index equivalents from the CSD [SRC: CARDDEMO.CSD]
-- CARDAIX: legacy alternate index on CARDDATA keyed by account id
CREATE INDEX IDX_CARD_ACCT_ID ON CARD (CARD_ACCT_ID);
-- CXACAIX: legacy "ALTERNATE INDEX TO CCXREF VIA ACCOUNT KEY"
CREATE INDEX IDX_CARD_XREF_ACCT_ID ON CARD_XREF (XREF_ACCT_ID);
